var n=`0995-dan-bing`;var a=`world-0995`;var t=`TW`;var s=`east-asia`;var l=4;var o=44;var r={en:`Dan Bing`,ua:`Дань бін`};var g={en:`Dan Bing is a Taiwan dish made with all-purpose flour, chicken egg, light soy sauce, chili garlic sauce. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Дань бін, страва кухні країни Тайвань. Основні складники: пшеничне борошно універсальне, куряче яйце, світлий соєвий соус, часниковий соус чилі. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`all-purpose-flour`,200,`g`],[`water`,300,`ml`],[`chicken-egg`,3,`pcs`],[`table-salt`,5,`g`]]},{en:`Swirl thin layers of batter in a lightly greased hot pan. Cook both sides, about 17 minutes per batch, to make flexible crepes.`,ua:`Наливайте тонкий шар тіста на злегка змащену розігріту сковороду. Обсмажуйте з обох боків, приблизно 17 хвилин на партію, щоб отримати еластичні млинці.`,t:[`pan-frying`],m:17,i:[[`canola-oil`,42,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`light-soy-sauce`,55,`ml`],[`chili-garlic-sauce`,65,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:8,i:[[`green-onion`,70,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`white-sesame-seeds`,18,`g`]]}];var c={slug:n,id:a,country:`TW`,region:s,servings:4,minutes:44,title:r,text:g,steps:d};export{t as country,c as default,a as id,o as minutes,s as region,l as servings,n as slug,d as steps,g as text,r as title};